@startuml

class Center {
  + Name : string
  + Address : string
}

class Room {
  + Number : int
  + MaximumCapacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer extends Person {
  + Diploma : string
}

class Session {
  + Date : date
  + StartingHour : time
}

class GroupSession extends Session {
  + Type : string
}

class IndividualSession extends Session {
}

class Participation {
}

Center "1" *-- "1..*" Room

Center "1" -- "0..*" Session
Room "1" -- "0..*" Session

Session "0..*" -- "0..*" Person : Participation

Session "0..*" -- "1" Trainer : supervises

@enduml

